use maho_rpc::{host_successor::*,host_daemon_paths::*,host_daemon_state::*};
#[test]fn preparing_successor_inherits_policy_and_does_not_replace_public_socket(){let temp=tempfile::tempdir().unwrap();let socket=temp.path().join("s");let _listener=std::os::unix::net::UnixListener::bind(&socket).unwrap();let socket=socket.to_str().unwrap();let paths=create_host_daemon_paths(socket,temp.path());create_daemon_directories(&paths).unwrap();write_host_settings(&paths,&HostDaemonSettings{socket:socket.into(),capabilities:vec![],cold_start:"persistent".into(),idle_exit_ms:1234.,generation:1.,instance_id:"old".into()}).unwrap();let prepared=prepare_successor(socket,&paths,2,"new",None,&["--permission".into(),"read".into()]).unwrap();assert_eq!(prepared.bind_socket,format!("{socket}.next-2"));assert_eq!(maho_rpc::socket_ownership::stat_socket_identity(std::path::Path::new(socket)).unwrap(),Some(prepared.replaced));assert!(!std::path::Path::new(&prepared.bind_socket).exists());let settings=read_host_settings(&paths).unwrap().unwrap();assert_eq!(settings["coldStart"],"persistent");assert_eq!(settings["idleExitMs"],1234.);assert_eq!(&prepared.argv[6..],["--permission","read"]);assert!(generation_paths(&paths,"new").settings_file.exists());}
#[test]fn overlong_successor_path_refuses_before_writing_state(){let temp=tempfile::tempdir().unwrap();let paths=create_host_daemon_paths("s",temp.path());assert!(matches!(prepare_successor(&"a".repeat(104),&paths,2,"new",None,&[]),Err(PrepareSuccessorError::SocketPathTooLong(_))));assert!(!paths.dir.exists());}
